# -*- coding: utf-8 -*-
"""R75 S4 盲测生成脚本：B10/B11/B12 共60例，逐批append落盘。
每例字段: cid, pred, conf, trig(changed_main,reserve_used,disputed,reason),
ys(用神枚举), ws(旺衰), dh(动化方向行), fz(反转条件行), sl(四路), dx(对象对齐),
yq(应期程序), ft(R61复推与粒度核), note(残损/说明,可空)
basis 由模板组装: 首行逐字照录卡面 tradition 值。
"""
import json, pathlib
BASE = pathlib.Path("/home/hatch/workspace/divination/benchmark/phase3/runs/round75/predictions")
BASE.mkdir(parents=True, exist_ok=True)
CASES = []
def C(cid, pred, conf, trig, ys, ws, dh, fz, sl, dx, yq, ft, note=""):
    CASES.append(dict(cid=cid, pred=pred, conf=conf, trig=trig, ys=ys, ws=ws,
                      dh=dh, fz=fz, sl=sl, dx=dx, yq=yq, ft=ft, note=note))
def basis(c):
    lines = ["卡面 tradition＝liuyao",
             f"用神枚举：{c['ys']}",
             f"旺衰与决策序：{c['ws']}",
             f"动化方向：{c['dh']}",
             f"反转条件：{c['fz']}",
             f"四路：{c['sl']}",
             f"对象对齐：{c['dx']}",
             f"应期程序：{c['yq']}",
             f"双核复核：{c['ft']}"]
    if c['note']:
        lines.append(f"输入说明：{c['note']}")
    return "\n".join(lines)
def flush(expected_ids):
    got = []
    for c in CASES:
        cm, rv, dp, rs = c['trig']
        obj = {"case_id": c['cid'], "prediction_text": c['pred'], "basis": basis(c),
               "confidence": c['conf'],
               "trigger": {"changed_main": cm, "reserve_used": rv, "disputed": dp, "reason": rs}}
        (BASE / f"{c['cid']}.json").write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")
        got.append(c['cid'])
    assert got == expected_ids, (got, expected_ids)
    print("flushed", len(got), got[0], "->", got[-1])
    CASES.clear()

